    kept = [e for e in errors if "literal[UNSET]" not in e["loc"]] or errors
    return [
        {"path": prefix + _path(e["loc"], value, e["type"] == "missing"), "message": e["msg"], "code": e["type"]}
        for e in kept
    ]


